// Builds dist/ for the copy-paste install path (no clasp): one Code.gs + Dashboard.html + appsscript.json.
// Usage: node tools/bundle.js
const fs = require('node:fs');
const path = require('node:path');
const src = path.join(__dirname, '..', 'apps-script');
const out = path.join(__dirname, '..', 'dist');
fs.mkdirSync(out, { recursive: true });
const files = fs.readdirSync(src).filter((f) => f.endsWith('.js')).sort();
const code = files.map((f) => `// ===== ${f} =====\n${fs.readFileSync(path.join(src, f), 'utf8')}`).join('\n\n');
fs.writeFileSync(path.join(out, 'Code.gs'), `// GENERATED by tools/bundle.js from apps-script/*.js. Do not edit here.\n\n${code}`);
fs.copyFileSync(path.join(src, 'Dashboard.html'), path.join(out, 'Dashboard.html'));
fs.copyFileSync(path.join(src, 'appsscript.json'), path.join(out, 'appsscript.json'));
console.log(`dist/: Code.gs (${files.length} files), Dashboard.html, appsscript.json`);
